using System;using System.IO;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using TMPro;
public static class FixCinemaSign19 {public static object Main(){if(EditorApplication.isPlayingOrWillChangePlaymode||SceneManager.GetActiveScene().isDirty)throw new Exception("Clean Edit only");var root=GameObject.Find("Chapter45_World/DetailedMall_20261003/Scenery").transform;Transform floor=null;foreach(Transform t in root)if(t.name.StartsWith("6F ")&&t.name.Contains(" · "))floor=t;if(floor==null)throw new Exception("Existing 6F required");var sign=floor.Find("Arrival wayfinding/Floor sign");if(sign==null||sign.GetComponent<TMP_Text>()==null)throw new Exception("Existing sign required");var p=sign.position;if(Mathf.Abs(p.y-49.8f)>.02f)throw new Exception("Unexpected or already corrected sign");string copy="outputs/ch5-toon-2026-10-04/recovery-before-cinema-sign.unity";if(File.Exists(copy))throw new Exception("Preserve prior copy");File.Copy(SceneManager.GetActiveScene().path,copy,false);sign.position=new Vector3(p.x,51.7f,p.z);EditorSceneManager.MarkSceneDirty(SceneManager.GetActiveScene());EditorSceneManager.SaveScene(SceneManager.GetActiveScene());return new{oldHeightAboveFloor=4.8,newHeightAboveFloor=6.7,changedOnly="Existing 6F world-space arrival label position",cameraUnchanged=true,reason="At the straight 6F approach the original floating label crossed the hero's feet; move it overhead within the existing ceiling height."};}}
